<?php
/** AI fundamentals: what AI, ML, deep learning and generative AI are, data, training and inference, LLMs and their limits, uses, kinds of learning, multimodal AI, a short history. */

if (!function_exists('fig_aibase_circles')) {
    function fig_aibase_circles(string $ai, string $aie, string $ml, string $mle, string $dl, string $dle, string $gen, string $gene): string
    {
        return <<<SVG
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 400" font-family="system-ui, sans-serif" font-size="15" fill="#1E1C52"><rect x="14" y="14" width="612" height="372" rx="60" fill="#F1F0F8" stroke="#8A87B0" stroke-width="2"/><rect x="84" y="82" width="528" height="292" rx="60" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><rect x="164" y="150" width="436" height="212" rx="60" fill="#ECE6FF" stroke="#7048E8" stroke-width="2"/><rect x="244" y="218" width="344" height="132" rx="60" fill="#FFE8D6" stroke="#E8590C" stroke-width="2"/><text x="44" y="46" font-weight="700" fill="#4A4775">{$ai}</text><text x="44" y="66" font-size="13">{$aie}</text><text x="114" y="114" font-weight="700" fill="#1B66BC">{$ml}</text><text x="114" y="134" font-size="13">{$mle}</text><text x="194" y="182" font-weight="700" fill="#5A35D0">{$dl}</text><text x="194" y="202" font-size="13">{$dle}</text><text x="274" y="250" font-weight="700" fill="#B84508">{$gen}</text><text x="274" y="270" font-size="13">{$gene}</text></svg>
SVG;
    }
}

if (!function_exists('fig_aibase_learning')) {
    function fig_aibase_learning(string $sup, string $supd, string $uns, string $unsd, string $rl, string $rld, string $lab, string $groups, string $agent, string $env, string $action, string $reward): string
    {
        return <<<SVG
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 300" font-family="system-ui, sans-serif" font-size="15" fill="#1E1C52"><defs><marker id="lr" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L10 5L0 10z" fill="#1E1C52"/></marker></defs><rect x="14" y="14" width="196" height="272" rx="14" fill="#DCEBFF" stroke="#2F8CF0" stroke-width="2"/><text x="112" y="44" text-anchor="middle" font-weight="700" fill="#1B66BC">{$sup}</text><text x="112" y="270" text-anchor="middle" font-size="13">{$supd}</text><rect x="224" y="14" width="196" height="272" rx="14" fill="#D5F6EA" stroke="#0B7F5C" stroke-width="2"/><text x="322" y="44" text-anchor="middle" font-weight="700" fill="#0B7F5C">{$uns}</text><text x="322" y="270" text-anchor="middle" font-size="13">{$unsd}</text><rect x="434" y="14" width="196" height="272" rx="14" fill="#FFF3EA" stroke="#E8590C" stroke-width="2"/><text x="532" y="44" text-anchor="middle" font-weight="700" fill="#B84508">{$rl}</text><text x="532" y="270" text-anchor="middle" font-size="13">{$rld}</text><line x1="120" y1="80" x2="110" y2="235" stroke="#2F8CF0" stroke-width="2" stroke-dasharray="6 4"/><circle cx="50" cy="110" r="8" fill="#FFFFFF" stroke="#2F8CF0" stroke-width="2"/><circle cx="70" cy="150" r="8" fill="#FFFFFF" stroke="#2F8CF0" stroke-width="2"/><circle cx="95" cy="120" r="8" fill="#FFFFFF" stroke="#2F8CF0" stroke-width="2"/><circle cx="60" cy="195" r="8" fill="#FFFFFF" stroke="#2F8CF0" stroke-width="2"/><path d="M150 90L159 106L141 106z" fill="#2F8CF0"/><path d="M170 140L179 156L161 156z" fill="#2F8CF0"/><path d="M140 180L149 196L131 196z" fill="#2F8CF0"/><path d="M175 200L184 216L166 216z" fill="#2F8CF0"/><text x="112" y="248" text-anchor="middle" font-size="12" fill="#1B66BC">{$lab}</text><circle cx="270" cy="120" r="40" fill="none" stroke="#0B7F5C" stroke-width="2" stroke-dasharray="5 4"/><circle cx="255" cy="110" r="6" fill="#0B7F5C"/><circle cx="280" cy="102" r="6" fill="#0B7F5C"/><circle cx="275" cy="128" r="6" fill="#0B7F5C"/><circle cx="258" cy="136" r="6" fill="#0B7F5C"/><circle cx="290" cy="132" r="6" fill="#0B7F5C"/><circle cx="350" cy="190" r="40" fill="none" stroke="#0B7F5C" stroke-width="2" stroke-dasharray="5 4"/><circle cx="335" cy="180" r="6" fill="#0B7F5C"/><circle cx="360" cy="172" r="6" fill="#0B7F5C"/><circle cx="355" cy="198" r="6" fill="#0B7F5C"/><circle cx="338" cy="206" r="6" fill="#0B7F5C"/><circle cx="370" cy="202" r="6" fill="#0B7F5C"/><text x="320" y="248" text-anchor="middle" font-size="12" fill="#0B7F5C">{$groups}</text><rect x="460" y="80" width="140" height="44" rx="10" fill="#FFFFFF" stroke="#E8590C" stroke-width="2"/><text x="530" y="107" text-anchor="middle" font-size="14" font-weight="700">{$agent}</text><rect x="460" y="190" width="140" height="44" rx="10" fill="#FFFFFF" stroke="#E8590C" stroke-width="2"/><text x="530" y="217" text-anchor="middle" font-size="14" font-weight="700">{$env}</text><path d="M580 126 V186" stroke="#1E1C52" stroke-width="2" marker-end="url(#lr)"/><path d="M480 188 V128" stroke="#1E1C52" stroke-width="2" marker-end="url(#lr)"/><text x="586" y="162" font-size="12">{$action}</text><text x="474" y="162" text-anchor="end" font-size="12">{$reward}</text></svg>
SVG;
    }
}

if (!function_exists('fig_aibase_timeline')) {
    function fig_aibase_timeline(string $winter, string $e1, string $e2, string $e3, string $e4, string $e5, string $e6, string $note): string
    {
        return <<<SVG
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 640 290" font-family="system-ui, sans-serif" font-size="15" fill="#1E1C52"><rect x="223.4" y="60" width="27.8" height="150" rx="6" fill="#FFE3EE"/><rect x="283.7" y="60" width="27.8" height="150" rx="6" fill="#FFE3EE"/><text x="237.3" y="230" text-anchor="middle" font-size="13" fill="#C2185B">{$winter}</text><text x="297.6" y="248" text-anchor="middle" font-size="13" fill="#C2185B">{$winter}</text><line x1="30" y1="140" x2="615" y2="140" stroke="#8A87B0" stroke-width="3"/><line x1="50" y1="140" x2="50" y2="118" stroke="#E8590C" stroke-width="2"/><circle cx="50" cy="140" r="7" fill="#E8590C"/><text x="40" y="96" text-anchor="start" font-weight="700" font-size="14">1950 · Turing</text><text x="40" y="114" text-anchor="start" font-size="13" fill="#4A4775">{$e1}</text><line x1="140" y1="140" x2="140" y2="162" stroke="#E8590C" stroke-width="2"/><circle cx="140" cy="140" r="7" fill="#E8590C"/><text x="140" y="182" text-anchor="middle" font-weight="700" font-size="14">1956 · Dartmouth</text><text x="140" y="200" text-anchor="middle" font-size="13" fill="#4A4775">{$e2}</text><line x1="330" y1="140" x2="330" y2="118" stroke="#E8590C" stroke-width="2"/><circle cx="330" cy="140" r="7" fill="#E8590C"/><text x="330" y="96" text-anchor="middle" font-weight="700" font-size="14">1997 · Deep Blue</text><text x="330" y="114" text-anchor="middle" font-size="13" fill="#4A4775">{$e3}</text><line x1="430" y1="140" x2="430" y2="162" stroke="#E8590C" stroke-width="2"/><circle cx="430" cy="140" r="7" fill="#E8590C"/><text x="430" y="182" text-anchor="middle" font-weight="700" font-size="14">2012 · AlexNet</text><text x="430" y="200" text-anchor="middle" font-size="13" fill="#4A4775">{$e4}</text><line x1="520" y1="140" x2="520" y2="118" stroke="#E8590C" stroke-width="2"/><circle cx="520" cy="140" r="7" fill="#E8590C"/><text x="520" y="96" text-anchor="middle" font-weight="700" font-size="14">2017 · Transformer</text><text x="520" y="114" text-anchor="middle" font-size="13" fill="#4A4775">{$e5}</text><line x1="600" y1="140" x2="600" y2="162" stroke="#E8590C" stroke-width="2"/><circle cx="600" cy="140" r="7" fill="#E8590C"/><text x="612" y="182" text-anchor="end" font-weight="700" font-size="14">2022 · ChatGPT</text><text x="612" y="200" text-anchor="end" font-size="13" fill="#4A4775">{$e6}</text><text x="320" y="278" text-anchor="middle" font-size="13" fill="#5E5B85">{$note}</text></svg>
SVG;
    }
}

return [
    'id' => 'ai-base', 'family' => 'ai', 'after' => null,
    'title' => L('Fondamenti di AI', 'AI Fundamentals'), 'short' => L('AI base', 'AI Basics'), 'level' => L('Base', 'Basics'),
    'desc' => L('Che cos’è davvero l’intelligenza artificiale: machine learning, deep learning, AI generativa, dati, addestramento, modelli linguistici e loro limiti, tipi di apprendimento, AI multimodale e un po’ di storia.', 'What artificial intelligence really is: machine learning, deep learning, generative AI, data, training, language models and their limits, kinds of learning, multimodal AI and a bit of history.'),
    'lessons' => [
        lesson('what', L('Che cos’è l’AI', 'What AI is'), [
            P('**Intelligenza artificiale** è il nome largo per i sistemi che svolgono compiti che di solito richiedono intelligenza umana: riconoscere immagini, capire testi, tradurre, giocare, decidere. Dentro ci sono cerchi sempre più piccoli.', '**Artificial intelligence** is the broad name for systems that perform tasks that usually need human intelligence: recognising images, understanding text, translating, playing, deciding. Inside it sit ever smaller circles.'),
            P('Il **machine learning** (ML) è l’AI che impara dagli esempi invece di seguire regole scritte a mano. Il **deep learning** è il ML fatto con reti neurali a molti strati. L’**AI generativa** usa il deep learning per *creare* contenuti nuovi: testo, immagini, audio, codice.', '**Machine learning** (ML) is AI that learns from examples instead of following hand-written rules. **Deep learning** is ML done with many-layered neural networks. **Generative AI** uses deep learning to *create* new content: text, images, audio, code.'),
            Fig(L(fig_aibase_circles('Intelligenza artificiale', 'regole scritte a mano o apprese', 'Machine learning', 'impara dagli esempi', 'Deep learning', 'reti neurali a molti strati', 'AI generativa', 'crea testo, immagini'), fig_aibase_circles('Artificial intelligence', 'hand-written or learned rules', 'Machine learning', 'learns from examples', 'Deep learning', 'many-layered neural networks', 'Generative AI', 'creates text, images')),
                L('Quattro riquadri arrotondati uno dentro l’altro: il più grande è l’intelligenza artificiale, dentro c’è il machine learning, dentro ancora il deep learning e al centro l’AI generativa.', 'Four rounded boxes one inside the other: the largest is artificial intelligence, inside it machine learning, inside that deep learning and at the centre generative AI.'),
                L('Ogni cerchio è un caso particolare di quello che lo contiene.', 'Each circle is a special case of the one that contains it.')),
            C('AI
└── Machine learning        impara dai dati
    └── Deep learning       reti neurali profonde
        └── AI generativa   crea testo, immagini, audio', 'text'),
            Tip('Un filtro antispam a regole (“se contiene ‘vinci subito’ allora spam”) è AI ma non ML. Uno che impara da migliaia di email etichettate è ML.', 'A rule-based spam filter (“if it says ‘win now’ then spam”) is AI but not ML. One that learns from thousands of labelled emails is ML.'),
        ], [
            Q('w1', L('Che cosa distingue il machine learning?', 'What sets machine learning apart?'), [L('Impara dagli esempi', 'It learns from examples'), L('Usa solo regole scritte a mano', 'It only uses hand-written rules'), L('Funziona senza dati', 'It works without data'), L('È sempre generativo', 'It is always generative')], 0, L('Le regole le ricava dai dati.', 'It derives the rules from data.')),
            Q('w2', L('Il deep learning è…', 'Deep learning is…'), [L('ML con reti neurali a molti strati', 'ML with many-layered neural networks'), L('Un database molto grande', 'A very large database'), L('L’opposto del ML', 'The opposite of ML'), L('Un linguaggio di programmazione', 'A programming language')], 0, L('“Profondo” per i tanti strati.', '“Deep” because of the many layers.')),
            Q('w3', L('Quale di questi è AI generativa?', 'Which of these is generative AI?'), [L('Un modello che scrive un racconto', 'A model that writes a story'), L('Un termostato', 'A thermostat'), L('Un foglio di calcolo', 'A spreadsheet'), L('Un filtro a regole fisse', 'A fixed-rule filter')], 0, L('Crea contenuti nuovi.', 'It creates new content.')),
        ], task('text', L('Scrivi su tre righe un esempio per ciascuno: una riga che inizia con `ML:`, una con `DL:` e una con `GenAI:`.', 'Write one example of each on three lines: a line starting with `ML:`, one with `DL:` and one with `GenAI:`.'), "ML: \nDL: \nGenAI: ", [re('^ML:\s*\S.{3,}', L('Un esempio di ML', 'An ML example')), re('^DL:\s*\S.{3,}', L('Un esempio di deep learning', 'A deep learning example')), re('^GenAI:\s*\S.{3,}', L('Un esempio di AI generativa', 'A generative AI example'))], '', "ML: prevedere il prezzo di una casa\nDL: riconoscere i volti nelle foto\nGenAI: scrivere una mail con un chatbot"), [
            dMatch(pMatch(), [['AI', L('Il campo intero', 'The whole field')], ['ML', L('Impara dai dati', 'Learns from data')], ['Deep learning', L('Reti neurali profonde', 'Deep neural networks')], [L('AI generativa', 'Generative AI'), L('Crea contenuti', 'Creates content')]], L('I cerchi uno dentro l’altro.', 'Circles one inside another.')),
            dFlash(pFlash(), [[L('Tutto il ML è AI', 'All ML is AI'), true], [L('Tutta l’AI è deep learning', 'All AI is deep learning'), false], [L('L’AI generativa usa il deep learning', 'Generative AI uses deep learning'), true], [L('Un sistema a regole fisse è machine learning', 'A fixed-rule system is machine learning'), false]], L('Dal generale al particolare.', 'From general to specific.')),
        ]),
        lesson('data', L('Dati, addestramento e inferenza', 'Data, training and inference'), [
            P('Un modello di ML nasce in due fasi. Nell’**addestramento** (training) guarda moltissimi esempi e regola i suoi **parametri** per sbagliare sempre meno. Nell’**inferenza** usa i parametri imparati per rispondere su dati nuovi.', 'An ML model is born in two phases. In **training** it looks at many examples and adjusts its **parameters** to make fewer and fewer mistakes. In **inference** it uses the learned parameters to answer on new data.'),
            C('dati di esempio ──► addestramento ──► modello (parametri)
nuovo dato ─────────────────────────► modello ──► previsione', 'text'),
            P('La qualità dei dati conta più di tutto: dati pochi, sporchi o sbilanciati producono un modello scarso o ingiusto (“garbage in, garbage out”). Per misurarlo onestamente si tiene da parte un **test set** che il modello non ha mai visto.', 'Data quality matters most: little, dirty or skewed data produces a poor or unfair model (“garbage in, garbage out”). To measure it honestly you keep aside a **test set** the model has never seen.'),
        ], [
            Q('d1', L('Che cosa succede durante l’addestramento?', 'What happens during training?'), [L('Il modello regola i parametri sugli esempi', 'The model tunes its parameters on examples'), L('Il modello risponde agli utenti', 'The model answers users'), L('Si cancellano i dati', 'The data is deleted'), L('Si scrive il codice dell’app', 'The app code is written')], 0, L('L’inferenza viene dopo.', 'Inference comes after.')),
            Q('d2', L('Che cos’è l’inferenza?', 'What is inference?'), [L('Usare il modello su dati nuovi', 'Using the model on new data'), L('Raccogliere dati', 'Collecting data'), L('Ripulire i dati', 'Cleaning the data'), L('Comprare GPU', 'Buying GPUs')], 0, L('È quello che fai quando chatti con un modello.', 'It is what you do when you chat with a model.')),
            Q('d3', L('Perché si tiene da parte un test set?', 'Why keep a test set aside?'), [L('Per misurare il modello su dati mai visti', 'To measure the model on unseen data'), L('Per addestrare più velocemente', 'To train faster'), L('Per risparmiare spazio', 'To save space'), L('Per fare un backup', 'To make a backup')], 0, L('Altrimenti il voto sarebbe falsato.', 'Otherwise the score would be inflated.')),
        ], task('text', L('Indica per ciascuna attività se è `training` o `inferenza`, una per riga nel formato `attività: fase`. Attività: `chatbot risponde`, `il modello impara da 1 milione di foto`.', 'For each activity say whether it is `training` or `inference`, one per line as `activity: phase`. Activities: `chatbot answers`, `model learns from 1 million photos`.'), '', [re('(chatbot risponde|chatbot answers)\s*:\s*(inferenza|inference)', L('Il chatbot fa inferenza', 'The chatbot does inference')), re('(il modello impara|model learns)[^:\n]*:\s*training', L('Imparare è training', 'Learning is training'))], '', "chatbot risponde: inferenza\nil modello impara da 1 milione di foto: training"), [
            dOrder(pSort(), [L('Raccogli i dati', 'Collect the data'), L('Pulisci ed etichetta', 'Clean and label'), L('Addestra il modello', 'Train the model'), L('Valuta sul test set', 'Evaluate on the test set'), L('Usa il modello (inferenza)', 'Use the model (inference)')], L('Il ciclo di vita di un modello.', 'A model’s life cycle.')),
            dFlash(pFlash(), [[L('Dati migliori battono spesso modelli più grandi', 'Better data often beats bigger models'), true], [L('Il test set si usa anche per addestrare', 'The test set is also used for training'), false], [L('I parametri si regolano durante il training', 'Parameters are tuned during training'), true], [L('L’inferenza cambia i parametri del modello', 'Inference changes the model’s parameters'), false]], L('Prima si impara, poi si usa.', 'First learn, then use.')),
        ]),
        lesson('llm', L('Come funziona un modello linguistico', 'How a language model works'), [
            P('Un **LLM** (Large Language Model) come quelli dietro ChatGPT, Claude o Gemini è addestrato su enormi quantità di testo a fare una cosa sola: prevedere il **token** successivo. Un token è un pezzo di parola: “intelligenza” può diventare “intel” + “ligenza”.', 'An **LLM** (Large Language Model) like those behind ChatGPT, Claude or Gemini is trained on huge amounts of text to do one thing: predict the next **token**. A token is a piece of a word: “intelligence” may become “intel” + “ligence”.'),
            C('“Il gatto sale sul” → tetto (62%) · tavolo (21%) · divano (9%) …', 'text'),
            P('Ripetendo la previsione token dopo token il modello scrive frasi intere. Dopo il pre-addestramento viene rifinito con esempi di conversazione e con il feedback umano, perché segua le istruzioni e risponda in modo utile e sicuro. La **finestra di contesto** è quanto testo il modello può considerare in una volta.', 'Repeating the prediction token after token, the model writes whole sentences. After pre-training it is refined with conversation examples and human feedback, so it follows instructions and answers helpfully and safely. The **context window** is how much text the model can consider at once.'),
        ], [
            Q('l1', L('Che cosa fa, alla base, un LLM?', 'What does an LLM do, at its core?'), [L('Prevede il token successivo', 'Predicts the next token'), L('Cerca la risposta in un database', 'Looks the answer up in a database'), L('Copia pagine web intere', 'Copies whole web pages'), L('Esegue regole scritte a mano', 'Runs hand-written rules')], 0, L('Un token dopo l’altro.', 'One token after another.')),
            Q('l2', L('Che cos’è un token?', 'What is a token?'), [L('Un pezzo di testo, spesso parte di una parola', 'A piece of text, often part of a word'), L('Una password', 'A password'), L('Una moneta digitale', 'A digital coin'), L('Una riga di codice', 'A line of code')], 0, L('Si paga e si misura in token.', 'You pay and measure in tokens.')),
            Q('l3', L('Che cos’è la finestra di contesto?', 'What is the context window?'), [L('Quanto testo il modello considera in una volta', 'How much text the model considers at once'), L('La finestra della chat', 'The chat window'), L('Il tempo di risposta', 'The response time'), L('Il numero di utenti', 'The number of users')], 0, L('Oltre quel limite il testo non entra.', 'Beyond that limit text does not fit.')),
        ], task('text', L('Spiega in una frase che cosa fa un LLM, usando le parole `token` e `prevedere` (o `predict`).', 'Explain in one sentence what an LLM does, using the words `token` and `predict` (or `prevedere`).'), '', [re('token', L('Parli di token', 'You mention tokens')), re('preved|predict', L('Parli di previsione', 'You mention prediction'))], '', 'Un LLM scrive un testo prevedendo un token alla volta, il più probabile dopo quelli precedenti.'), [
            dMatch(pMatch(), [['LLM', L('Modello linguistico grande', 'Large language model')], ['Token', L('Pezzo di testo', 'Piece of text')], [L('Contesto', 'Context'), L('Testo considerato insieme', 'Text considered together')], [L('Pre-addestramento', 'Pre-training'), L('Imparare da tanto testo', 'Learning from lots of text')], [L('Feedback umano', 'Human feedback'), L('Rifinire il comportamento', 'Refining behaviour')]], L('Il vocabolario degli LLM.', 'LLM vocabulary.')),
            dFlash(pFlash(), [[L('Un LLM legge parole intere, mai pezzi', 'An LLM reads whole words, never pieces'), false], [L('Un LLM scrive un token alla volta', 'An LLM writes one token at a time'), true], [L('La finestra di contesto è illimitata', 'The context window is unlimited'), false], [L('Il feedback umano aiuta a seguire le istruzioni', 'Human feedback helps follow instructions'), true]], L('Previsione, non magia.', 'Prediction, not magic.')),
        ]),
        lesson('limits', L('Limiti e allucinazioni', 'Limits and hallucinations'), [
            P('Un LLM produce testo **plausibile**, non necessariamente vero. Quando inventa fatti, citazioni o fonti con sicurezza si parla di **allucinazione**. Non è un bug raro: è una conseguenza di come funziona.', 'An LLM produces **plausible** text, not necessarily true text. When it confidently invents facts, quotes or sources it is called a **hallucination**. It is not a rare bug: it follows from how it works.'),
            P('Altri limiti: la **data di taglio** (non conosce i fatti successivi all’addestramento, se non può cercare sul web), i calcoli lunghi, i **bias** ereditati dai dati. Le difese: chiedere le fonti e controllarle, dare al modello i documenti giusti, verificare numeri e codice.', 'Other limits: the **knowledge cutoff** (it does not know events after training, unless it can search the web), long calculations, **biases** inherited from data. Defences: ask for sources and check them, give the model the right documents, verify numbers and code.'),
            Tip('Usa l’AI come un collega brillante ma distratto: ottimo per bozze e idee, da ricontrollare quando conta.', 'Treat AI like a brilliant but absent-minded colleague: great for drafts and ideas, to be double-checked when it matters.'),
        ], [
            Q('h1', L('Che cos’è un’allucinazione?', 'What is a hallucination?'), [L('Un’informazione inventata detta con sicurezza', 'Made-up information stated confidently'), L('Un errore di rete', 'A network error'), L('Un’immagine generata', 'A generated image'), L('Un modello spento', 'A model that is off')], 0, L('Plausibile non vuol dire vero.', 'Plausible does not mean true.')),
            Q('h2', L('Che cos’è la data di taglio?', 'What is the knowledge cutoff?'), [L('Il limite dei fatti che il modello conosce', 'The limit of facts the model knows'), L('La scadenza dell’abbonamento', 'The subscription expiry'), L('La lunghezza massima della risposta', 'The maximum answer length'), L('L’ora di manutenzione', 'The maintenance hour')], 0, L('Dopo quella data non sa, a meno che cerchi.', 'After that date it does not know, unless it searches.')),
            Q('h3', L('Qual è una buona difesa dalle allucinazioni?', 'What is a good defence against hallucinations?'), [L('Verificare le fonti citate', 'Checking the cited sources'), L('Fare domande più lunghe', 'Asking longer questions'), L('Usare il maiuscolo', 'Using capital letters'), L('Ripetere la domanda finché piace la risposta', 'Repeating the question until you like the answer')], 0, L('Le fonti si controllano.', 'Sources must be checked.')),
        ], task('text', L('Riscrivi questa richiesta in modo che riduca le allucinazioni: chiedi esplicitamente le `fonti` e di dire `non lo so` se non è sicuro. Richiesta: “Chi ha inventato il primo compilatore?”', 'Rewrite this request to reduce hallucinations: explicitly ask for `sources` and to say `I don’t know` if unsure. Request: “Who invented the first compiler?”'), 'Chi ha inventato il primo compilatore?', [re('compilator|compiler', L('Mantieni la domanda', 'You keep the question')), re('font[ie]|sources?', L('Chiedi le fonti', 'You ask for sources')), re('non lo so|non (sei|è) sicur|don.t know|not sure', L('Ammetti l’incertezza', 'You allow uncertainty'))], '', 'Chi ha inventato il primo compilatore? Indica le fonti e, se non sei sicuro, dimmi “non lo so”.'), [
            dMatch(pMatch(), [[L('Allucinazione', 'Hallucination'), L('Fatto inventato', 'Made-up fact')], [L('Data di taglio', 'Cutoff'), L('Fatti recenti sconosciuti', 'Recent facts unknown')], ['Bias', L('Pregiudizi dai dati', 'Prejudice from data')], [L('Verifica', 'Verification'), L('Controllare fonti e numeri', 'Checking sources and numbers')]], L('Conoscere i limiti per usarla bene.', 'Know the limits to use it well.')),
            dFlash(pFlash(), [[L('Un LLM può inventare una citazione', 'An LLM can invent a quote'), true], [L('Se risponde con sicurezza, è sicuramente vero', 'If it answers confidently, it is surely true'), false], [L('I dati di addestramento possono contenere pregiudizi', 'Training data can contain bias'), true], [L('Un LLM conosce sempre le notizie di oggi', 'An LLM always knows today’s news'), false]], L('Fiducia, ma con verifica.', 'Trust, but verify.')),
        ]),
        lesson('uses', L('Dove si usa l’AI', 'Where AI is used'), [
            P('L’AI è già ovunque: **classificazione** (spam, diagnosi da immagini), **previsione** (vendite, traffico, meteo), **raccomandazione** (film, prodotti), **visione** (volti, guida assistita), **linguaggio** (traduzione, riassunti, chatbot), **generazione** (testo, immagini, codice, musica).', 'AI is already everywhere: **classification** (spam, image diagnosis), **forecasting** (sales, traffic, weather), **recommendation** (films, products), **vision** (faces, driver assistance), **language** (translation, summaries, chatbots), **generation** (text, images, code, music).'),
            P('Prima di usarla chiediti: il compito ha dati a sufficienza? Un errore è grave? Serve una spiegazione della decisione? Per compiti ad alto rischio (salute, credito, giustizia) servono controlli umani e, in Europa, le regole dell’**AI Act**.', 'Before using it ask yourself: does the task have enough data? Is a mistake serious? Is an explanation of the decision needed? For high-risk tasks (health, credit, justice) you need human oversight and, in Europe, the rules of the **AI Act**.'),
        ], [
            Q('u1', L('Suggerire un film in base a quelli visti è…', 'Suggesting a film based on those you watched is…'), [L('Raccomandazione', 'Recommendation'), L('Visione', 'Vision'), L('Traduzione', 'Translation'), L('Compressione', 'Compression')], 0, L('Impara dai gusti simili.', 'It learns from similar tastes.')),
            Q('u2', L('Quale compito è ad alto rischio?', 'Which task is high risk?'), [L('Decidere chi riceve un prestito', 'Deciding who gets a loan'), L('Suggerire una canzone', 'Suggesting a song'), L('Correggere un refuso', 'Fixing a typo'), L('Scegliere un emoji', 'Picking an emoji')], 0, L('Tocca diritti e opportunità.', 'It touches rights and opportunities.')),
            Q('u3', L('Quale legge europea regola l’AI?', 'Which European law regulates AI?'), ['AI Act', 'GDPR Act', 'Digital Cookie Act', 'Code Act'], 0, L('Classifica i sistemi per livello di rischio.', 'It classifies systems by risk level.')),
        ], task('text', L('Abbina tre usi al loro tipo, uno per riga come `uso: tipo`. Usi: `filtro antispam`, `previsione delle vendite`, `traduzione automatica`. Tipi: classificazione, previsione, linguaggio.', 'Match three uses to their type, one per line as `use: type`. Uses: `spam filter`, `sales forecast`, `machine translation`. Types: classification, forecasting, language.'), '', [re('(antispam|spam)[^:\n]*:\s*(classificazione|classification)', L('Lo spam è classificazione', 'Spam is classification')), re('(vendite|sales)[^:\n]*:\s*(previsione|forecast)', L('Le vendite sono previsione', 'Sales are forecasting')), re('(traduzione|translation)[^:\n]*:\s*(linguaggio|language)', L('La traduzione è linguaggio', 'Translation is language'))], '', "filtro antispam: classificazione\nprevisione delle vendite: previsione\ntraduzione automatica: linguaggio"), [
            dMatch(pMatch(), [[L('Filtro antispam', 'Spam filter'), L('Classificazione', 'Classification')], [L('Meteo di domani', 'Tomorrow’s weather'), L('Previsione', 'Forecasting')], [L('Prodotti consigliati', 'Recommended products'), L('Raccomandazione', 'Recommendation')], [L('Riconoscere volti', 'Recognising faces'), L('Visione', 'Vision')], [L('Riassunto di un testo', 'Text summary'), L('Linguaggio', 'Language')]], L('Ogni problema il suo tipo.', 'Each problem its type.')),
            dFlash(pFlash(), [[L('Per decisioni sanitarie serve un controllo umano', 'Health decisions need human oversight'), true], [L('L’AI Act riguarda solo i videogiochi', 'The AI Act only covers video games'), false], [L('Senza dati sufficienti il ML funziona male', 'Without enough data ML works poorly'), true], [L('Ogni problema si risolve meglio con l’AI', 'Every problem is best solved with AI'), false]], L('Lo strumento giusto al posto giusto.', 'The right tool in the right place.')),
        ]),
        lesson('learning', L('Tre modi di imparare', 'Three ways to learn'), [
            P('Nell’apprendimento **supervisionato** il modello impara da esempi con la risposta giusta: foto etichettate “gatto” o “cane”, case con il loro prezzo. È il caso più comune.', 'In **supervised** learning the model learns from examples with the right answer: photos labelled “cat” or “dog”, houses with their price. It is the most common case.'),
            P('Nel **non supervisionato** le risposte non ci sono: il modello cerca da solo somiglianze e gruppi, per esempio clienti con abitudini simili. Nell’apprendimento **per rinforzo** un agente prova azioni e riceve **premi** o penalità, come chi impara un videogioco giocando: così si addestrano robot e programmi che giocano, e anche gli assistenti a dare risposte migliori.', 'In **unsupervised** learning there are no answers: the model finds similarities and groups by itself, for example customers with similar habits. In **reinforcement** learning an agent tries actions and gets **rewards** or penalties, like someone learning a video game by playing: that is how robots and game-playing programs are trained, and assistants too, to give better answers.'),
            Fig(L(fig_aibase_learning('Supervisionato', 'esempi con la risposta', 'Non supervisionato', 'solo esempi', 'Per rinforzo', 'azioni e premi', 'confine appreso', 'gruppi trovati', 'agente', 'ambiente', 'azione', 'premio'), fig_aibase_learning('Supervised', 'examples with the answer', 'Unsupervised', 'examples only', 'Reinforcement', 'actions and rewards', 'learned boundary', 'groups found', 'agent', 'environment', 'action', 'reward')),
                L('Tre pannelli. Supervisionato: cerchi e triangoli già etichettati, separati da una linea tratteggiata appresa. Non supervisionato: punti tutti uguali che il modello raccoglie in due gruppi. Per rinforzo: un agente manda un’azione all’ambiente e riceve un premio.', 'Three panels. Supervised: circles and triangles already labelled, split by a learned dashed line. Unsupervised: identical points that the model gathers into two groups. Reinforcement: an agent sends an action to the environment and gets a reward back.'),
                L('Che cosa ricevi cambia che cosa puoi imparare: risposte, solo dati, o premi.', 'What you receive changes what you can learn: answers, data only, or rewards.')),
            C('supervisionato   esempi + risposte giuste  → prevedere      (spam / non spam)
non supervisionato solo esempi             → trovare gruppi  (segmenti di clienti)
per rinforzo     azioni + premi            → imparare a agire (giocare, guidare un robot)', 'text'),
        ], [
            Q('m1', L('Raggruppare clienti simili senza sapere in anticipo i gruppi è apprendimento…', 'Grouping similar customers without knowing the groups in advance is…'), [L('Supervisionato, con le etichette', 'Supervised, with labels'), L('Per rinforzo, con i premi', 'Reinforcement, with rewards'), L('Non supervisionato, senza risposte', 'Unsupervised, with no answers'), L('A regole scritte a mano', 'Based on hand-written rules')], 2, L('Nessuno gli dice quali sono i gruppi.', 'Nobody tells it what the groups are.')),
            Q('m2', L('Che cosa riceve un agente nell’apprendimento per rinforzo?', 'What does an agent receive in reinforcement learning?'), [L('Premi o penalità per le sue azioni', 'Rewards or penalties for its actions'), L('Un elenco di risposte giuste già pronte', 'A ready list of right answers'), L('Solo dati senza alcun riscontro', 'Only data with no feedback at all'), L('Le regole scritte dal programmatore', 'The rules written by the programmer')], 0, L('Impara provando e sbagliando.', 'It learns by trial and error.')),
            Q('m3', L('Riconoscere cifre scritte a mano da migliaia di esempi etichettati è…', 'Recognising handwritten digits from thousands of labelled examples is…'), [L('Non supervisionato', 'Unsupervised'), L('Supervisionato', 'Supervised'), L('Per rinforzo', 'Reinforcement'), L('Nessun tipo di ML', 'No kind of ML')], 1, L('Ogni esempio ha la sua risposta.', 'Each example has its answer.')),
        ], task('text', L('Abbina tre casi al tipo di apprendimento, uno per riga come `caso: tipo`. Casi: `spam`, `gruppi di clienti`, `robot che impara a camminare`. Tipi: supervisionato, non supervisionato, rinforzo.', 'Match three cases to the kind of learning, one per line as `case: kind`. Cases: `spam`, `customer groups`, `robot learning to walk`. Kinds: supervised, unsupervised, reinforcement.'), '', [re('spam[^:\n]*:\s*(supervisionato|supervised)', L('Lo spam è supervisionato', 'Spam is supervised')), re('(gruppi|groups)[^:\n]*:\s*(non supervisionato|unsupervised)', L('I gruppi sono non supervisionati', 'Groups are unsupervised')), re('robot[^:\n]*:\s*(per )?(rinforzo|reinforcement)', L('Il robot impara per rinforzo', 'The robot learns by reinforcement'))], '', "spam: supervisionato\ngruppi di clienti: non supervisionato\nrobot che impara a camminare: rinforzo"), [
            dMatch(pMatch(), [[L('Supervisionato', 'Supervised'), L('Esempi con risposta', 'Examples with answers')], [L('Non supervisionato', 'Unsupervised'), L('Cerca gruppi da solo', 'Finds groups by itself')], [L('Per rinforzo', 'Reinforcement'), L('Premi e penalità', 'Rewards and penalties')], [L('Etichetta', 'Label'), L('La risposta giusta', 'The right answer')]], L('Tre famiglie di apprendimento.', 'Three families of learning.')),
            dFlash(pFlash(), [[L('Nel supervisionato ogni esempio ha la risposta', 'In supervised learning each example has the answer'), true], [L('Il clustering ha bisogno di etichette', 'Clustering needs labels'), false], [L('Il rinforzo impara da premi e penalità', 'Reinforcement learns from rewards and penalties'), true], [L('Un robot che impara giocando usa il supervisionato', 'A robot learning by playing uses supervised learning'), false]], L('Con risposte, senza risposte, con premi.', 'With answers, without, with rewards.')),
        ]),
        lesson('multimodal', L('Oltre il testo: immagini, voce, video', 'Beyond text: images, voice, video'), [
            P('Un modello **multimodale** lavora con più tipi di dati: legge una foto e ne descrive il contenuto, capisce un grafico, ascolta una domanda a voce. Molti assistenti di oggi accettano testo, immagini, documenti e audio nella stessa conversazione.', 'A **multimodal** model works with several kinds of data: it reads a photo and describes what is in it, understands a chart, listens to a spoken question. Many of today’s assistants accept text, images, documents and audio in the same conversation.'),
            P('Per **generare** immagini e video si usano spesso i modelli di **diffusione**: partono da puro rumore e lo ripuliscono passo dopo passo finché compare l’immagine descritta dal prompt. Per la voce ci sono il **riconoscimento vocale** (dall’audio al testo) e la **sintesi vocale** (dal testo a una voce realistica).', 'To **generate** images and video, **diffusion** models are often used: they start from pure noise and clean it step by step until the image described by the prompt appears. For voice there is **speech recognition** (from audio to text) and **speech synthesis** (from text to a realistic voice).'),
            Tip('Più potere creativo vuol dire anche più rischio di falsi credibili: per questo molte immagini generate portano marchi invisibili o etichette che ne dichiarano l’origine.', 'More creative power also means more risk of convincing fakes: that is why many generated images carry invisible watermarks or labels declaring their origin.'),
        ], [
            Q('x1', L('Che cosa sa fare un modello multimodale?', 'What can a multimodal model do?'), [L('Lavorare solo con testo, ma più in fretta', 'Work only with text, but faster'), L('Funzionare senza essere addestrato', 'Work without being trained'), L('Tradurre solo tra più lingue', 'Only translate between languages'), L('Capire più tipi di dati, come testo e immagini', 'Understand several kinds of data, like text and images')], 3, L('Testo, immagini, audio, video.', 'Text, images, audio, video.')),
            Q('x2', L('Da dove parte un modello di diffusione per creare un’immagine?', 'Where does a diffusion model start from to create an image?'), [L('Da un’immagine presa dal web e ritoccata', 'From a web image that it retouches'), L('Da puro rumore, ripulito passo dopo passo', 'From pure noise, cleaned step by step'), L('Da un disegno fatto a mano dall’utente', 'From a hand drawing made by the user'), L('Da un archivio di immagini già pronte', 'From an archive of ready-made images')], 1, L('Il rumore diventa immagine.', 'Noise becomes an image.')),
            Q('x3', L('Trasformare un messaggio vocale in testo è…', 'Turning a voice message into text is…'), [L('Sintesi vocale', 'Speech synthesis'), L('Generazione di immagini', 'Image generation'), L('Riconoscimento vocale', 'Speech recognition'), L('Diffusione', 'Diffusion')], 2, L('Dall’audio al testo.', 'From audio to text.')),
        ], task('text', L('Scrivi tre esempi di uso multimodale, uno per riga, che inizino con `Immagine:`, `Voce:` e `Documento:`.', 'Write three examples of multimodal use, one per line, starting with `Image:`, `Voice:` and `Document:`.'), "Immagine: \nVoce: \nDocumento: ", [re('^(Immagine|Image):\s*\S.{3,}', L('Un esempio con un’immagine', 'An example with an image')), re('^(Voce|Voice):\s*\S.{3,}', L('Un esempio con la voce', 'An example with voice')), re('^(Documento|Document):\s*\S.{3,}', L('Un esempio con un documento', 'An example with a document'))], '', "Immagine: fotografo una pianta e chiedo che cos’è\nVoce: detto una nota e la ricevo scritta\nDocumento: carico una bolletta in PDF e chiedo il totale"), [
            dMatch(pMatch(), [[L('Multimodale', 'Multimodal'), L('Più tipi di dati', 'Several kinds of data')], [L('Diffusione', 'Diffusion'), L('Dal rumore all’immagine', 'From noise to image')], [L('Riconoscimento vocale', 'Speech recognition'), L('Audio → testo', 'Audio → text')], [L('Sintesi vocale', 'Speech synthesis'), L('Testo → voce', 'Text → voice')]], L('L’AI oltre le parole.', 'AI beyond words.')),
            dFlash(pFlash(), [[L('Un assistente può descrivere una foto', 'An assistant can describe a photo'), true], [L('I modelli di diffusione copiano un’immagine esistente', 'Diffusion models copy an existing image'), false], [L('La sintesi vocale può imitare una voce reale', 'Speech synthesis can imitate a real voice'), true], [L('Un modello multimodale capisce solo il testo', 'A multimodal model only understands text'), false]], L('Testo, immagini, suoni.', 'Text, images, sounds.')),
        ]),
        lesson('history', L('Breve storia dell’AI', 'A short history of AI'), [
            P('Nel 1950 Alan Turing si chiede se le macchine possano pensare e propone il suo famoso test. Nel 1956, al convegno di **Dartmouth**, nasce il nome “intelligenza artificiale”. Seguono decenni di entusiasmi e delusioni: quando le promesse non si realizzano, i fondi calano (gli **inverni dell’AI**).', 'In 1950 Alan Turing asks whether machines can think and proposes his famous test. In 1956, at the **Dartmouth** workshop, the name “artificial intelligence” is born. Decades of enthusiasm and disappointment follow: when promises fail, funding dries up (the **AI winters**).'),
            Fig(L(fig_aibase_timeline('inverno dell’AI', 'le macchine pensano?', 'nasce il nome', 'batte Kasparov', 'vince sulle immagini', 'l’architettura degli LLM', 'LLM per tutti', 'Le zone rosa sono gli inverni dell’AI: pochi risultati, pochi fondi.'), fig_aibase_timeline('AI winter', 'can machines think?', 'the name is born', 'beats Kasparov', 'wins at images', 'the LLM architecture', 'LLMs for everyone', 'The pink zones are the AI winters: few results, little funding.')),
                L('Una linea del tempo dal 1950 al 2022 con sei tappe: 1950 Turing, 1956 Dartmouth, 1997 Deep Blue, 2012 AlexNet, 2017 transformer, 2022 ChatGPT. Due fasce rosa, a metà degli anni Settanta e tra fine anni Ottanta e inizio Novanta, segnano gli inverni dell’AI.', 'A timeline from 1950 to 2022 with six milestones: 1950 Turing, 1956 Dartmouth, 1997 Deep Blue, 2012 AlexNet, 2017 transformer, 2022 ChatGPT. Two pink bands, in the mid-1970s and from the late 1980s to the early 1990s, mark the AI winters.'),
                L('Settant’anni di storia, non in scala: le tappe si fittiscono dopo il 2010.', 'Seventy years of history, not to scale: the milestones crowd together after 2010.')),
            C('1950  Turing: “Le macchine possono pensare?”
1956  Dartmouth: nasce il termine “intelligenza artificiale”
1997  Deep Blue batte Kasparov a scacchi
2012  AlexNet: il deep learning vince nel riconoscimento di immagini
2017  Il transformer, l’architettura dei modelli linguistici
2022  ChatGPT porta i modelli linguistici al grande pubblico', 'text'),
            P('La svolta recente nasce da tre ingredienti insieme: **tanti dati** (il web), **calcolo** a basso costo (le GPU) e **algoritmi** migliori (reti profonde, transformer). Nessuno dei tre basta da solo.', 'The recent breakthrough comes from three ingredients together: **lots of data** (the web), cheap **compute** (GPUs) and better **algorithms** (deep networks, transformers). None of the three is enough alone.'),
        ], [
            Q('s1', L('Quando nasce il termine “intelligenza artificiale”?', 'When was the term “artificial intelligence” coined?'), [L('Nel 2012, con AlexNet', 'In 2012, with AlexNet'), L('Nel 1997, con Deep Blue', 'In 1997, with Deep Blue'), L('Nel 2022, con ChatGPT', 'In 2022, with ChatGPT'), L('Nel 1956, a Dartmouth', 'In 1956, at Dartmouth')], 3, L('Un convegno estivo negli Stati Uniti.', 'A summer workshop in the United States.')),
            Q('s2', L('Che cosa sono gli “inverni dell’AI”?', 'What are the “AI winters”?'), [L('Periodi di delusione e pochi fondi', 'Periods of disappointment and little funding'), L('Mesi in cui i server si raffreddano', 'Months when servers cool down'), L('Versioni dell’AI per i paesi freddi', 'AI versions for cold countries'), L('Pause estive dei laboratori di ricerca', 'Summer breaks of research labs')], 0, L('Le promesse non mantenute costano.', 'Broken promises cost.')),
            Q('s3', L('Quali ingredienti hanno reso possibile la svolta recente?', 'Which ingredients made the recent breakthrough possible?'), [L('Solo computer più veloci', 'Only faster computers'), L('Dati, calcolo e algoritmi migliori insieme', 'Data, compute and better algorithms together'), L('Solo leggi più favorevoli', 'Only more favourable laws'), L('Solo più programmatori nel mondo', 'Only more programmers in the world')], 1, L('Servono tutti e tre.', 'All three are needed.')),
        ], task('text', L('Metti in ordine quattro tappe, una per riga numerate da `1.` a `4.`: transformer, Dartmouth, ChatGPT, AlexNet.', 'Put four milestones in order, one per line numbered `1.` to `4.`: transformer, Dartmouth, ChatGPT, AlexNet.'), "1. \n2. \n3. \n4. ", [re('^1\.\s*.*Dartmouth', L('Prima Dartmouth', 'Dartmouth first')), re('^2\.\s*.*AlexNet', L('Poi AlexNet', 'Then AlexNet')), re('^3\.\s*.*transformer', L('Poi il transformer', 'Then the transformer')), re('^4\.\s*.*ChatGPT', L('Infine ChatGPT', 'Finally ChatGPT'))], '', "1. Dartmouth (1956)\n2. AlexNet (2012)\n3. transformer (2017)\n4. ChatGPT (2022)"), [
            dOrder(pSort(), [L('Turing si chiede se le macchine pensano', 'Turing asks whether machines think'), L('Nasce il termine “intelligenza artificiale”', 'The term “artificial intelligence” is born'), L('Deep Blue batte Kasparov', 'Deep Blue beats Kasparov'), L('AlexNet e il deep learning', 'AlexNet and deep learning'), L('Arriva il transformer', 'The transformer arrives')], L('Settant’anni in cinque righe.', 'Seventy years in five lines.')),
            dFlash(pFlash(), [[L('Il termine AI è nato negli anni Cinquanta', 'The term AI was born in the 1950s'), true], [L('L’AI è cresciuta sempre senza battute d’arresto', 'AI has always grown without setbacks'), false], [L('Le GPU hanno aiutato la svolta del deep learning', 'GPUs helped the deep learning breakthrough'), true], [L('Il transformer è stato inventato nel 1956', 'The transformer was invented in 1956'), false]], L('Una storia di alti e bassi.', 'A story of ups and downs.')),
        ]),
